43	    Directory,
44	    File(Arc<RwLock<Vec<u8>>>),
45	    /// A file whose content is read live from the SHM state tree at open time.
46	    /// Only used for read-only view mounts. `plugin_id` is a catalog-known
47	    /// name (validated during capture); `pointer` is a JSON pointer into the
48	    /// plugin's state object. `schema` is pinned from the sealed blob.
49	    LiveFile {
50	        plugin_id: String,
51	        pointer: String,
52	    },
