63	impl Namespace {
64	    pub fn build(
65	        store: &ObjectStore,
66	        target: ProjectionTarget,
67	        state_dir: Option<&std::path::Path>,
68	    ) -> Result<Self> {
69	        let (view, workspace) = match &target {
70	            ProjectionTarget::View(id) => (store.read_view(id)?, None),
71	            ProjectionTarget::Workspace(id) => {
72	                let workspace = store.read_workspace(id)?;
73	                let view = store.read_view(&workspace.base_view)?;
74	                (view, Some(workspace))
75	            }
76	        };
77	        // View mounts read live state from SHM; workspace mounts use frozen COW.
78	        let live = workspace.is_none() && state_dir.is_some();
79	        let mut builder = NamespaceBuilder::new(target.clone(), state_dir.map(|p| p.to_path_buf()));
80	        builder.add_root_metadata(&view, workspace.as_ref())?;
81	
82	        let plugins = builder.add_dir(ROOT_INO, "plugins")?;
83	        let operations = builder.add_dir(ROOT_INO, "operations")?;
84	        let relationships = builder.add_dir(ROOT_INO, "relationships")?;
85	        let dependencies = builder.add_dir(relationships, "dependencies")?;
86	        let capabilities = builder.add_dir(ROOT_INO, "capabilities")?;
87	
88	        for plugin_id in view.objects.keys() {
89	            let object = match &workspace {
90	                Some(workspace) => store.workspace_object(workspace, plugin_id)?,
91	                None => store.object_for_view(&view, plugin_id)?,
92	            };
93	            let plugin_name = encode_component(plugin_id);
94	            let plugin_dir = builder.add_dir(plugins, &plugin_name)?;
95	            builder.add_json(plugin_dir, "object.blob.json", &object, None)?;
96	            builder.add_json(plugin_dir, "schema.json", &object.schema, None)?;
97	            if live {
98	                builder.add_live_file(plugin_dir, "value.json", plugin_id, "")?;
99	            } else {
100	                builder.add_json(plugin_dir, "value.json", &object.value, None)?;
101	            }
102	            builder.add_json(
103	                plugin_dir,
104	                "capabilities.json",
105	                &object.schema.capabilities(),
106	                None,
107	            )?;
108	            builder.add_text(
109	                plugin_dir,
110	                "object.hash",
111	                format!(
112	                    "{}\n",
113	                    object_hash_for_target(&view, workspace.as_ref(), plugin_id)?
114	                )
115	                .into_bytes(),
116	                None,
117	            )?;
118	
119	            let data_dir = builder.add_dir(plugin_dir, "data")?;
120	            let workspace_id = workspace
121	                .as_ref()
122	                .map(|workspace| workspace.workspace_id.clone());
123	            builder.add_value_children(
124	                data_dir,
125	                plugin_id,
126	                "",
127	                &object.value,
128	                Some(&object.schema),
129	                None,
130	                workspace_id.as_deref(),
131	                !object.schema.tags.iter().any(|tag| tag == "immutable"),
132	                live,
133	            )?;
134	
135	            let methods_dir = builder.add_dir(plugin_dir, "operations")?;
136	            let root_methods_dir = builder.add_dir(operations, &plugin_name)?;
137	            for (method_name, method) in &object.schema.methods {
138	                let encoded = encode_component(method_name);
139	                let method_dir = builder.add_dir(methods_dir, &encoded)?;
140	                builder.add_json(method_dir, "input.schema.json", &method.args, None)?;
141	                if let Some(returns) = &method.returns {
142	                    builder.add_json(method_dir, "output.schema.json", returns, None)?;
143	                }
144	                builder.add_json(method_dir, "metadata.json", method, None)?;
145	                builder.add_symlink(
146	                    root_methods_dir,
147	                    &encoded,
148	                    format!("/plugins/{plugin_name}/operations/{encoded}"),
149	                )?;
150	
151	                if let Some(capability) = &method.required_capability {
152	                    let capability_dir =
153	                        builder.add_dir_idempotent(capabilities, &encode_component(capability))?;
154	                    builder.add_symlink(
155	                        capability_dir,
156	                        &format!("{plugin_name}.{}", encode_component(method_name)),
157	                        format!("/plugins/{plugin_name}/operations/{encoded}"),
158	                    )?;
159	                }
160	            }
161	
162	            let relation_dir = builder.add_dir(dependencies, &plugin_name)?;
163	            for dependency in &object.schema.dependencies {
164	                builder.add_symlink(
165	                    relation_dir,
166	                    &encode_component(dependency),
167	                    format!("/plugins/{}", encode_component(dependency)),
168	                )?;
169	            }
170	        }
171	
172	        Ok(builder.finish())
173	    }
