345	fn resolve_target(store: &ObjectStore, args: &TargetArgs) -> Result<ProjectionTarget> {
346	    match (&args.view, &args.workspace) {
347	        (Some(view), None) => {
348	            store.read_view(view)?;
349	            Ok(ProjectionTarget::View(view.clone()))
350	        }
351	        (None, Some(workspace)) => {
352	            store.read_workspace(workspace)?;
353	            Ok(ProjectionTarget::Workspace(workspace.clone()))
354	        }
355	        (None, None) => {
356	            Ok(ProjectionTarget::View(store.current_view_id()?.context(
357	                "no current view; run `3tchedfs capture` first",
358	            )?))
359	        }
360	        (Some(_), Some(_)) => unreachable!("clap rejects conflicting targets"),
361	    }
362	}
363	
364	fn input_json(inline: Option<&str>, file: Option<&PathBuf>) -> Result<Value> {
365	    let text = match (inline, file) {
366	        (_, Some(path)) => fs::read_to_string(path)
367	            .with_context(|| format!("read JSON input {}", path.display()))?,
368	        (Some("-"), None) => {
369	            let mut text = String::new();
370	            std::io::stdin().read_to_string(&mut text)?;
371	            text
372	        }
373	        (Some(text), None) => text.to_string(),
374	        (None, None) => bail!("provide --json or --file"),
375	    };
376	    serde_json::from_str(&text).context("parse JSON input")
377	}
378	
379	fn print_json(value: &impl Serialize) -> Result<()> {
380	    println!("{}", serde_json::to_string_pretty(value)?);
381	    Ok(())
382	}
