127:export async function fetchIssuedIdentity(
143:export async function resolveIdentity(fetchImpl: typeof fetch = fetch): Promise<ProjectedIdentity | null> {
151:export function renewalDelayMs(identity: ProjectedIdentity, nowSeconds: number = Date.now() / 1000): number | null {
