sed -i 's|^const TTL: Duration = Duration::ZERO;|/// Kernel cache lifetime for a pinned view. Its tree never changes, and file
/// contents stay live because every open uses direct I/O. Workspaces rebuild
/// their tree on write, so they are never cached.
const VIEW_TTL: Duration = Duration::from_secs(1);

/// Identifies one committed version of a state file. MutationEngine replaces
/// the file on every commit, so a new commit always yields a new key.
#[derive(Clone, Copy, PartialEq, Eq)]
struct StateKey {
    dev: u64,
    ino: u64,
    mtime: i64,
    mtime_nsec: i64,
    len: u64,
}

impl StateKey {
    fn of(metadata: \&std::fs::Metadata) -> Self {
        use std::os::unix::fs::MetadataExt;
        Self {
            dev: metadata.dev(),
            ino: metadata.ino(),
            mtime: metadata.mtime(),
            mtime_nsec: metadata.mtime_nsec(),
            len: metadata.len(),
        }
    }
}|' $F && \
sed -i 's|^    outcomes: HashMap<(String, String), Outcome>,
}|X|' $F && \
awk '
/^    outcomes: HashMap<\(String, String\), Outcome>,$/ && !done1 {print; print "    ttl: Duration,"; print "    /// Rendered live files, keyed by (plugin, pointer), valid for one state version."; print "    live_cache: parking_lot::Mutex<HashMap<(String, String), (StateKey, Vec<u8>)>>,"; done1=1; next}
/^            outcomes: HashMap::new\(\),$/ && !done2 {print; print "            ttl: match namespace.target {"; print "                ProjectionTarget::View(_) => VIEW_TTL,"; print "                ProjectionTarget::Workspace(_) => Duration::ZERO,"; print "            },"; print "            live_cache: parking_lot::Mutex::new(HashMap::new()),"; done2=1; next}
{print}' $F > $F.new && mv $F.new $F && \
sed -i 's|&TTL|\&self.ttl|g' $F && grep -n -E 'VIEW_TTL|self.ttl|live_cache|ttl: match' $F | head -20

