async function fetchIdentityDocument(
  fetchImpl: typeof fetch,
  url: string,
  init: RequestInit,
): Promise<ProjectedIdentity | null> {
  const controller = new AbortController();
  let timeout: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      (async (): Promise<ProjectedIdentity | null> => {
        const response = await fetchImpl(url, {
          ...init,
          signal: controller.signal,
          cache: "no-store",
          headers: { accept: "application/json" },
        });
        if (!response.ok) return null;
        const body: unknown = await response.json();
        if (!body || typeof body !== "object") return null;
        const record = body as Record<string, unknown>;
        if (!isDoorIdentity(record.identity)) return null;
        const door = typeof record.door === "string" && record.door.trim() ? record.door.trim() : defaultDoorUrl();
        if (!door) return null;
        const expiresAt =
          typeof document.expires_at === "number" && Number.isFinite(document.expires_at) ? document.expires_at : undefined;
        return {
          door,
          identity: document.identity,
          sessionId: typeof document.session_id === "string" ? document.session_id : undefined,
          expiresAt,
        };
      })(),
      new Promise<null>((resolve) => {
        timeout = setTimeout(() => {
          record(`no answer within ${IDENTITY_PICKUP_TIMEOUT_MS / 1000} s`);
          controller.abort();
          resolve(null);
        }, IDENTITY_PICKUP_TIMEOUT_MS);
      }),
    ]);
  } catch {
    // A browser reports an unreachable host and a CORS refusal the same way.
    record("no answer (unreachable, or it does not allow this page's origin)");
    return null;
  } finally {
    if (timeout) clearTimeout(timeout);
  }
}
