8	pub const FORMAT_VERSION: &str = "3tchedfs/1";
9	
10	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
11	pub struct TypedObjectBlob {
12	    pub format: String,
13	    pub plugin_id: String,
14	    pub source_schema_hash: String,
15	    pub schema: PluginSchema,
16	    pub value: Value,
17	}
18	
19	impl TypedObjectBlob {
20	    pub fn new(
21	        plugin_id: String,
22	        source_schema_hash: String,
23	        schema: PluginSchema,
24	        value: Value,
25	    ) -> Result<Self> {
26	        let blob = Self {
27	            format: FORMAT_VERSION.to_string(),
28	            plugin_id,
29	            source_schema_hash,
30	            schema,
31	            value,
32	        };
33	        blob.validate(None)?;
34	        Ok(blob)
35	    }
36	
37	    pub fn validate(&self, base: Option<&Value>) -> Result<()> {
38	        if self.format != FORMAT_VERSION {
39	            bail!("unsupported typed object format '{}'", self.format);
40	        }
41	        if self.schema.name != self.plugin_id {
42	            bail!(
43	                "schema name '{}' does not match plugin id '{}'",
44	                self.schema.name,
45	                self.plugin_id
46	            );
47	        }
48	        self.schema.validate_value(&self.value, base)
49	    }
50	}
51	
52	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
53	pub struct PluginSchema {
54	    pub name: String,
55	    #[serde(default)]
56	    pub category: String,
57	    pub version: String,
58	    #[serde(default)]
59	    pub description: String,
60	    #[serde(default)]
61	    pub display_name: Option<String>,
62	    #[serde(default)]
63	    pub fields: BTreeMap<String, FieldSchema>,
64	    #[serde(default)]
65	    pub dependencies: Vec<String>,
66	    #[serde(default)]
67	    pub immutable_paths: Vec<String>,
68	    #[serde(default)]
69	    pub tags: Vec<String>,
70	    #[serde(default)]
71	    pub dialect: String,
72	    #[serde(default)]
73	    pub mutation_index: Option<u64>,
74	    #[serde(default)]
75	    pub subids: BTreeMap<String, String>,
76	    #[serde(default)]
77	    pub org: Option<String>,
78	    #[serde(default)]
79	    pub methods: BTreeMap<String, MethodDecl>,
80	    #[serde(default)]
81	    pub signals: Vec<SignalDecl>,
82	    #[serde(default)]
83	    pub guarantees: PluginGuarantees,
84	}
85	
86	impl PluginSchema {
87	    pub fn validate_value(&self, root: &Value, base: Option<&Value>) -> Result<()> {
88	        let object = root
89	            .as_object()
90	            .with_context(|| format!("{} state must be an object", self.name))?;
91	
92	        for (name, field) in &self.fields {
93	            match object.get(name) {
94	                Some(value) => field
95	                    .validate(value, root)
96	                    .with_context(|| format!("field /{name}"))?,
97	                None if field.required => bail!("required field /{name} is missing"),
98	                None => {}
99	            }
100	        }
101	
102	        if let Some(base) = base {
103	            let base_object = base
104	                .as_object()
105	                .with_context(|| format!("base {} state must be an object", self.name))?;
106	            validate_object_immutability(&self.fields, object, base_object, "")?;
107	
108	            for pointer in &self.immutable_paths {
109	                if root.pointer(pointer) != base.pointer(pointer) {
110	                    bail!("immutable path {pointer} changed");
111	                }
112	            }
113	
114	            if self.tags.iter().any(|tag| tag == "immutable") && root != base {
115	                bail!("plugin {} is immutable", self.name);
116	            }
117	        }
118	
119	        Ok(())
120	    }
121	
122	    pub fn template(&self) -> Value {
123	        let values = self
124	            .fields
125	            .iter()
126	            .map(|(name, schema)| (name.clone(), schema.template()))
127	            .collect();
128	        Value::Object(values)
129	    }
130	
131	    pub fn capabilities(&self) -> BTreeSet<&str> {
132	        self.methods
133	            .values()
134	            .filter_map(|method| method.required_capability.as_deref())
135	            .collect()
136	    }
137	}
138	
139	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
140	pub struct FieldSchema {
141	    pub field_type: FieldType,
142	    #[serde(default)]
143	    pub required: bool,
144	    #[serde(default)]
145	    pub description: String,
146	    #[serde(default)]
147	    pub default: Option<Value>,
148	    #[serde(default)]
149	    pub example: Option<Value>,
150	    #[serde(default)]
151	    pub constraints: Vec<Constraint>,
152	    #[serde(default)]
153	    pub read_only: bool,
154	    #[serde(default)]
155	    pub read_only_when: Option<ReadOnlyCondition>,
156	}
157	
158	impl FieldSchema {
159	    pub fn validate(&self, value: &Value, root: &Value) -> Result<()> {
160	        // PluginSchema represents `Option<T>` as a non-required T while live
161	        // state may preserve an explicit JSON null for that option.
162	        if value.is_null() && !self.required {
163	            return Ok(());
164	        }
165	        self.field_type.validate(value, root)?;
166	        for constraint in &self.constraints {
167	            constraint.validate(value, root)?;
168	        }
169	        Ok(())
170	    }
171	
172	    pub fn template(&self) -> Value {
173	        self.default
174	            .clone()
175	            .or_else(|| self.example.clone())
176	            .unwrap_or_else(|| self.field_type.template())
177	    }
178	}
