180	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
181	#[serde(rename_all = "snake_case")]
182	pub enum FieldType {
183	    String,
184	    Integer,
185	    Float,
186	    Boolean,
187	    Array(Box<FieldType>),
188	    Object(BTreeMap<String, FieldSchema>),
189	    /// Dynamic string keys with one declared value type. Wire form matches
190	    /// op-state-store: `{"map": <FieldType>}`.
191	    Map(Box<FieldType>),
192	    /// Explicit exact JSON Schema document retained from the sealed plugin.
193	    /// Wire form matches op-state-store: `{"json_schema": <document>}`.
194	    JsonSchema(Box<Value>),
195	    Enum(Vec<String>),
196	    OneOf(Vec<FieldType>),
197	    Any,
198	}
199	
200	impl FieldType {
201	    pub fn validate(&self, value: &Value, root: &Value) -> Result<()> {
202	        match self {
203	            Self::String if !value.is_string() => bail!("expected string"),
204	            Self::Integer if !value.is_i64() && !value.is_u64() => bail!("expected integer"),
205	            Self::Float if !value.is_number() => bail!("expected number"),
206	            Self::Boolean if !value.is_boolean() => bail!("expected boolean"),
207	            Self::Array(item_type) => {
208	                let values = value.as_array().context("expected array")?;
209	                for (index, value) in values.iter().enumerate() {
210	                    item_type
211	                        .validate(value, root)
212	                        .with_context(|| format!("array element {index}"))?;
213	                }
214	            }
215	            Self::Object(fields) => {
216	                let object = value.as_object().context("expected object")?;
217	                for (name, field) in fields {
218	                    match object.get(name) {
219	                        Some(value) => field
220	                            .validate(value, root)
221	                            .with_context(|| format!("object field {name}"))?,
222	                        None if field.required => bail!("required object field {name} is missing"),
223	                        None => {}
224	                    }
225	                }
226	            }
227	            Self::Map(item_type) => {
228	                let object = value.as_object().context("expected object map")?;
229	                for (index, value) in object.values().enumerate() {
230	                    // Dynamic keys may be private; keep errors key-agnostic.
231	                    item_type
232	                        .validate(value, root)
233	                        .with_context(|| format!("map value {index}"))?;
234	                }
235	            }
236	            Self::JsonSchema(schema) => {
237	                jsonschema::Validator::new(schema)
238	                    .context("compile embedded json_schema field")?
239	                    .validate(value)
240	                    .map_err(|error| anyhow::anyhow!("value failed json_schema: {error}"))?;
241	            }
242	            Self::Enum(variants) => {
243	                let value = value.as_str().context("expected enum string")?;
244	                if !variants.iter().any(|variant| variant == value) {
245	                    bail!("'{value}' is not an allowed enum value");
246	                }
247	            }
248	            Self::OneOf(branches) => {
249	                let matches = branches
250	                    .iter()
251	                    .filter(|branch| branch.validate(value, root).is_ok())
252	                    .count();
253	                // The current schemars adapter reduces some discriminated
254	                // variants to the same FieldType shape. Require at least one
255	                // matching branch; the sealed JSON Schema remains available
256	                // in the object for stricter discriminator-aware consumers.
257	                if matches == 0 {
258	                    bail!("value does not match any union branch");
259	                }
260	            }
261	            Self::Any | Self::String | Self::Integer | Self::Float | Self::Boolean => {}
262	        }
263	        Ok(())
264	    }
265	
266	    pub fn template(&self) -> Value {
267	        match self {
268	            Self::String => Value::String(String::new()),
269	            Self::Integer => Value::from(0),
270	            Self::Float => Value::from(0.0),
271	            Self::Boolean => Value::Bool(false),
272	            Self::Array(_) => Value::Array(Vec::new()),
273	            Self::Object(fields) => Value::Object(
274	                fields
275	                    .iter()
276	                    .map(|(name, field)| (name.clone(), field.template()))
277	                    .collect(),
278	            ),
279	            Self::Map(_) => Value::Object(serde_json::Map::new()),
280	            Self::JsonSchema(schema) => json_schema_template(schema),
281	            Self::Any => Value::Null,
282	            Self::Enum(values) => values
283	                .first()
284	                .cloned()
285	                .map(Value::String)
286	                .unwrap_or(Value::Null),
287	            Self::OneOf(branches) => branches.first().map(Self::template).unwrap_or(Value::Null),
288	        }
289	    }
290	}
