299	#[serde(tag = "type", rename_all = "snake_case")]
300	pub enum Constraint {
301	    Min { value: f64 },
302	    Max { value: f64 },
303	    Pattern { regex: String },
304	    OneOf { values: Vec<Value> },
305	    RequiresField { field: String },
306	    Custom { validator: String },
307	}
308	
309	impl Constraint {
310	    fn validate(&self, value: &Value, root: &Value) -> Result<()> {
311	        match self {
312	            Self::Min { value: minimum } => {
313	                let actual = measure(value).context("min constraint requires number or length")?;
314	                if actual < *minimum {
315	                    bail!("{actual} is below minimum {minimum}");
316	                }
317	            }
318	            Self::Max { value: maximum } => {
319	                let actual = measure(value).context("max constraint requires number or length")?;
320	                if actual > *maximum {
321	                    bail!("{actual} exceeds maximum {maximum}");
322	                }
323	            }
324	            Self::Pattern { regex } => {
325	                let actual = value
326	                    .as_str()
327	                    .context("pattern constraint requires string")?;
328	                if !Regex::new(regex)
329	                    .with_context(|| format!("invalid schema regex '{regex}'"))?
330	                    .is_match(actual)
331	                {
332	                    bail!("value does not match pattern '{regex}'");
333	                }
334	            }
335	            Self::OneOf { values } if !values.contains(value) => {
336	                bail!("value is not in the allowed set");
337	            }
338	            Self::RequiresField { field } if root.get(field).is_none() => {
339	                bail!("required peer field '{field}' is missing");
340	            }
341	            // A custom validator names plugin code that this standalone
342	            // projection cannot execute. The plugin dispatch path remains the
343	            // final authority when a staged value is applied.
344	            Self::Custom { .. } | Self::OneOf { .. } | Self::RequiresField { .. } => {}
345	        }
346	        Ok(())
347	    }
348	}
