406	fn validate_object_immutability(
407	    fields: &BTreeMap<String, FieldSchema>,
408	    current: &serde_json::Map<String, Value>,
409	    base: &serde_json::Map<String, Value>,
410	    parent_pointer: &str,
411	) -> Result<()> {
412	    for (name, field) in fields {
413	        let pointer = push_pointer(parent_pointer, name);
414	        let current_value = current.get(name);
415	        let base_value = base.get(name);
416	        if field.read_only && current_value != base_value {
417	            bail!("read-only field {pointer} changed");
418	        }
419	        if let Some(condition) = &field.read_only_when {
420	            let trigger = base
421	                .get(&condition.property)
422	                .map(json_scalar_text)
423	                .as_deref()
424	                == Some(condition.value.as_str());
425	            if trigger && current_value != base_value {
426	                bail!("conditionally read-only field {pointer} changed");
427	            }
428	        }
429	        if let (Some(current_value), Some(base_value)) = (current_value, base_value) {
430	            validate_type_immutability(&field.field_type, current_value, base_value, &pointer)?;
431	        }
432	    }
433	    Ok(())
434	}
