436	fn validate_type_immutability(
437	    field_type: &FieldType,
438	    current: &Value,
439	    base: &Value,
440	    pointer: &str,
441	) -> Result<()> {
442	    match field_type {
443	        FieldType::Object(fields) => {
444	            if let (Some(current), Some(base)) = (current.as_object(), base.as_object()) {
445	                validate_object_immutability(fields, current, base, pointer)?;
446	            }
447	        }
448	        FieldType::Map(item_type) => {
449	            if let (Some(current), Some(base)) = (current.as_object(), base.as_object()) {
450	                for (key, current_value) in current {
451	                    if let Some(base_value) = base.get(key) {
452	                        validate_type_immutability(
453	                            item_type,
454	                            current_value,
455	                            base_value,
456	                            &push_pointer(pointer, key),
457	                        )?;
458	                    }
459	                }
460	            }
461	        }
462	        FieldType::Array(item_type) => {
463	            if let (Some(current), Some(base)) = (current.as_array(), base.as_array()) {
464	                for (index, (current, base)) in current.iter().zip(base).enumerate() {
465	                    validate_type_immutability(
466	                        item_type,
467	                        current,
468	                        base,
469	                        &push_pointer(pointer, &index.to_string()),
470	                    )?;
471	                }
472	            }
473	        }
474	        FieldType::OneOf(branches) => {
475	            for branch in branches {
476	                if branch.validate(current, current).is_ok() && branch.validate(base, base).is_ok()
477	                {
478	                    validate_type_immutability(branch, current, base, pointer)?;
479	                }
480	            }
481	        }
482	        FieldType::String
483	        | FieldType::Integer
484	        | FieldType::Float
485	        | FieldType::Boolean
486	        | FieldType::Enum(_)
487	        | FieldType::JsonSchema(_)
488	        | FieldType::Any => {}
489	    }
490	    Ok(())
491	}
