498	/// A value that satisfies `schema` when no live state file exists.
499	/// Missing plugin state is filled from this template and then validated.
500	fn json_schema_template(schema: &Value) -> Value {
501	    if let Some(const_value) = schema.get("const") {
502	        return const_value.clone();
503	    }
504	    if let Some(first) = schema
505	        .get("enum")
506	        .and_then(Value::as_array)
507	        .and_then(|items| items.first())
508	    {
509	        return first.clone();
510	    }
511	    match json_schema_type_name(schema) {
512	        Some("object") => {
513	            let mut object = serde_json::Map::new();
514	            let properties = schema.get("properties").and_then(Value::as_object);
515	            if let Some(required) = schema.get("required").and_then(Value::as_array) {
516	                for name in required.iter().filter_map(Value::as_str) {
517	                    let child = properties
518	                        .and_then(|fields| fields.get(name))
519	                        .unwrap_or(&Value::Null);
520	                    object.insert(name.to_string(), json_schema_template(child));
521	                }
522	            }
523	            Value::Object(object)
524	        }
525	        Some("array") => Value::Array(Vec::new()),
526	        Some("string") => Value::String(String::new()),
527	        Some("integer") => schema
528	            .get("minimum")
529	            .and_then(Value::as_i64)
530	            .map(Value::from)
531	            .unwrap_or_else(|| Value::from(0)),
532	        Some("number") => Value::from(0.0),
533	        Some("boolean") => Value::Bool(false),
534	        Some("null") => Value::Null,
535	        _ => schema
536	            .get("oneOf")
537	            .or_else(|| schema.get("anyOf"))
538	            .and_then(Value::as_array)
539	            .and_then(|branches| branches.first())
540	            .map(json_schema_template)
541	            .unwrap_or(Value::Null),
542	    }
543	}
544	
545	fn json_schema_type_name(schema: &Value) -> Option<&str> {
546	    match schema.get("type") {
547	        Some(Value::String(name)) => Some(name.as_str()),
548	        Some(Value::Array(names)) => names
549	            .iter()
550	            .filter_map(Value::as_str)
551	            .find(|name| *name != "null"),
552	        _ => None,
553	    }
554	}
